def transform(grid):
    # Fill the enclosed centers of outlined rectangular figures.
    # Color-2 is used for 4x4 outlines; the other observed cavities use 7.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            # Components are 4-connected; locate their bounding rectangle.
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            minr=min(y for y,x in comp); maxr=max(y for y,x in comp)
            minc=min(x for y,x in comp); maxc=max(x for y,x in comp)
            # A rectangular border component encloses an all-background rectangle.
            if maxr-minr>=2 and maxc-minc>=2:
                if all(grid[minr][x]==color and grid[maxr][x]==color for x in range(minc,maxc+1)) and all(grid[y][minc]==color and grid[y][maxc]==color for y in range(minr,maxr+1)):
                    fill = 2 if (maxr-minr==3 and maxc-minc==3) else 7
                    for y in range(minr+1,maxr):
                        for x in range(minc+1,maxc):
                            if grid[y][x]==bg: out[y][x]=fill
    return out
